def collabrium_page():
    overview='''<p>Modern teams often spread their work across disconnected tools. Collabrium brings project management, people, learning, community, reporting, and AI assistance into one enterprise workspace.</p><p>The challenge was to make those features behave as one system: a user’s tenant, role, project membership, and account state all affect what they can see and do.</p><div class="case-stat-grid"><div class="case-stat"><strong>290+</strong><span>HTTP API actions<br>across the platform</span></div><div class="case-stat"><strong>30</strong><span>Concrete API<br>controllers</span></div><div class="case-stat"><strong>13</strong><span>Functional areas<br>in the backend</span></div></div><div class="case-callout"><strong>A team project, with clear ownership.</strong>I served as Team Lead and Backend Developer in a four-person team with Abeer Ahmad, Hanan Issa, and Nada Asad, under Dr. Thaer Sammar’s supervision. These figures describe the shared platform’s scope.</div>'''
    contribution='''<p>I led the team through requirements analysis, two-week Agile sprints, implementation, integration, testing, and delivery. On the backend, I translated requirements into domain rules, API contracts, and application use cases.</p><ul><li>Developed the .NET 8 backend around <strong>Clean Architecture, CQRS/MediatR, EF Core, and SQL Server</strong>.</li><li>Worked on tenant isolation and layered authentication and authorization, including Identity, JWT, rotating refresh tokens, policies, and project access.</li><li>Implemented connected workflows spanning work items, sprints, reporting, real-time features, background processing, and AI assistance.</li><li>Contributed to React frontend implementation and API integration alongside the team.</li></ul>'''
    architecture=f'''<p>The solution separates the API, Application, Domain, and Infrastructure projects. The domain owns business rules; the application layer coordinates use cases through interfaces; infrastructure provides persistence and external integrations.</p><div class="architecture-diagram">{ARCHITECTURE}</div><p><strong>Commands and queries take different paths.</strong> Commands use domain models, repositories, and a Unit of Work. Queries use purpose-specific read models and DTO projections. Domain models and persistence entities are separated through explicit mappers.</p><div class="case-callout"><strong>Why that separation matters</strong>A work-item state change is a business operation with invariants and history. A report is a read operation with a purpose-built projection. Giving them separate paths keeps their responsibilities explicit.</div>'''
    decisions=collabrium_decisions()
    demo='<p>Five original recordings demonstrate project delivery, tenant and team workflows, reporting, the Learning Hub, and multi-tenant onboarding.</p>'+video_gallery('case')
    visuals=full_screen_gallery()
    project_story='<p>The project began with a problem we recognized: organizations connecting their work across separate tools. These original visuals introduce the team, that challenge, and the connected platform we delivered.</p>'+promo_gallery('case')
    documentation='<p>The final thesis records the requirements and system design in 272 pages. The updated 53-slide graduation presentation demonstrates the platform and its workflows.</p>'+resources()
    reflection='''<p>This project taught me to reason about features as parts of one domain. A sprint change can affect work-item relationships, reports, history, and notifications. Clear boundaries and explicit invariants make those connections easier to manage.</p><p>My next iteration would strengthen integration coverage for cross-tenant access and authorization, add request tracing, and profile the most expensive analytical queries.</p>'''
    sources='<p>Explore the public code and the team’s frontend showcase for the implementation and product walkthroughs.</p><div class="source-grid">'
    for url,label in [(GITHUB+'/Collabrium','Backend repository'),('https://github.com/NadaAsadk/Collabrium-Frontend-Showcase','Team frontend showcase'),(C+'Application/Features/WorkItems/Commands/CreateWorkItem.cs','Transactional work-item creation'),(C+'API/Middlewares/TentantMiddleware.cs','Tenant context middleware')]:
        sources+=ext(url,label)
    sources+='</div>'+linkedin_series()
    return case_page('collabrium','Collabrium','01 / Graduation project · Enterprise software','Many workflows. One connected workspace.','A multi-tenant enterprise platform connecting project delivery, people, learning, collaboration, reports, and AI-assisted workflows.','Team Lead &amp; Backend Developer','Oct 2025 — Jun 2026','Four-person graduation project',['.NET 8','ASP.NET Core','EF Core','SQL Server','CQRS','MediatR','Identity / JWT','SignalR','QuestPDF'],f'<div class="case-cover">{browser_image("collabrium-dashboard.webp","Collabrium tenant administration dashboard")}</div>','Actual product screen from the Collabrium project archive.',[('overview','The challenge',overview),('contribution','My contribution',contribution),('architecture','The architecture',architecture),('decisions','Engineering decisions',decisions),('demo','Watch the workflows',demo),('walkthrough','The product in practice',visuals),('project-story','The project story',project_story),('documentation','Thesis & presentation',documentation),('reflection','What I took forward',reflection),('sources','Explore the work',sources)],'actify','Actify')

def actify_page():
    overview='''<p>Actify is an activity-based social application: users can discover and create activities, manage attendance, follow people, maintain profiles, and join live discussions.</p><p>I built it as a course-based full-stack project while studying the Complete Guide to Building an App with .NET Core and React. It gave me a focused setting to connect backend use cases to a real React interface.</p>'''
    contribution='''<ul><li>Implemented REST API features using <strong>ASP.NET Core, EF Core, CQRS, and MediatR</strong>.</li><li>Worked with Identity-based account flows, activity creation and editing, attendance changes, user profiles, photo management, and follow relationships.</li><li>Integrated a <strong>React and TypeScript</strong> frontend using MUI, MobX, API hooks, forms, and protected routes.</li><li>Connected SignalR comments to the activity detail view, including loading previous comments and receiving new ones.</li></ul>'''
    decisions=decision(1,'Model attendance according to who is acting.','The attendance use case distinguishes the host from other attendees. A host can toggle cancellation; an attendee can leave; a new participant can join. One workflow represents three different user intentions.',A+'Application/Activities/Commands/UpdateAttendance.cs')
    decisions+=decision(2,'Make discussion activity-specific.','The comment hub joins each connection to its activity group, loads existing comments for the caller, and broadcasts new comments to that activity. The React hook manages the client connection and updates observable comment state.',A+'API/SignalR/CommentHub.cs')
    decisions+=decision(3,'Keep feature responsibilities visible end to end.','Application commands and queries express the backend use cases. React feature folders and dedicated hooks connect activities, accounts, and profiles to those endpoints, while shared components provide common form and navigation behavior.',A+'Client/src/lib/hooks/useComments.tsx')
    code=f'''<p>This excerpt shows how the hub routes a new discussion comment through the application layer, then broadcasts the returned comment to its activity group.</p><div class="case-code"><span class="label">API / SignalR / CommentHub.cs · source excerpt, reformatted</span>{codeblock(REALTIME_CODE)}</div>{ext(A+'API/SignalR/CommentHub.cs','Read the full comment hub','source-link')}'''
    reflection='''<p>Actify helped me connect backend concerns to the user experience: an attendance update changes what a participant sees, and a live comment has a connection lifecycle as well as a persistence path.</p><p>It was a learning project. The next iteration would focus on integration tests around attendance changes and on verifying discussion access at the activity boundary.</p>'''
    sources='<div class="source-grid">'+''.join(ext(u,t) for u,t in [(GITHUB+'/Actify','Project repository'),(A+'Application/Activities/Commands/UpdateAttendance.cs','Attendance workflow'),(A+'API/SignalR/CommentHub.cs','SignalR comment hub'),(A+'Client/src/lib/hooks/useComments.tsx','React discussion hook')])+'</div>'
    return case_page('actify','Actify','02 / Course-based project · Full-stack application','Activities bring people together. The backend connects the experience.','An activity-based social application with attendance workflows, profiles, following, and live discussion, built with ASP.NET Core and React.','Full-stack implementation','Aug 2025 — Sep 2025','Course-based learning project',['ASP.NET Core','React','TypeScript','EF Core','MediatR','SignalR','MUI','MobX'],f'<div class="case-cover illustration actify">{ACTIFY_ART}</div>','Feature relationship illustration based on the repository; this is not a product screenshot.',[('overview','The project',overview),('contribution','What I implemented',contribution),('decisions','Engineering decisions',decisions),('code','A closer look at the code',code),('reflection','What I took forward',reflection),('sources','Explore the work',sources)],'hotel-booking','Hotel Booking API')

def hotel_page():
    overview='''<p>The Hotel Booking Platform is a REST API developed as the final project of my backend internship at Foothill Technology Solutions. It covers the core hotel booking domain: guests, hotels, rooms, amenities, cities, discounts, reservations, reviews, and administration.</p><p>The project connected many of the concepts from training into one implementation: layered architecture, data modeling, validation, authentication, business rules, tests, documentation, and deployment.</p><div class="case-stat-grid"><div class="case-stat"><strong>50+</strong><span>Documented API<br>endpoints</span></div><div class="case-stat"><strong>9</strong><span>API controllers<br>in the repository</span></div><div class="case-stat"><strong>3</strong><span>OS targets in the<br>CI build/test matrix</span></div></div>'''
    contribution='''<ul><li>Implemented a <strong>.NET 8 REST API</strong> with EF Core, SQL Server, JWT authentication, and Clean Architecture.</li><li>Developed booking flows, search and filtering, room and hotel management, reviews, discounts, and guest access.</li><li>Added email notifications, invoice calculation, and <strong>PDF invoice generation</strong>.</li><li>Wrote xUnit tests, documented endpoints with Swagger and Postman, configured GitHub Actions CI, and deployed the API to Azure App Service.</li></ul>'''
    decisions=decision(1,'Validate the booking before persisting it.','The booking service resolves the hotel and current guest, retrieves the requested rooms and active discounts, validates the rooms, and calculates the price before saving the reservation.',H+'HotelBookingPlatform.Application/Services/BookingService.cs')
    decisions+=decision(2,'Make invoice calculations testable.','Dedicated tests cover the number of nights, total prices, per-room discount calculations, missing bookings, and guest ownership checks. These are domain outcomes with a direct effect on what a guest receives.',H+'HotelBookingBlatform.Tests/BookingServiceTests/BookingInvoiceCalculationsTests.cs')
    decisions+=decision(3,'Protect a guest’s booking data.','Reading a booking or invoice resolves the current guest and verifies that the guest owns the booking. Resource ownership complements authentication at the API boundary.',H+'HotelBookingPlatform.Application/Services/BookingService.cs')
    decisions+=decision(4,'Keep delivery steps explicit.','The public GitHub Actions workflow restores, builds, and tests .NET 8 across Ubuntu, Windows, and macOS. Azure App Service and Azure SQL were used in hands-on deployment; this workflow does not contain an Azure deployment step.',H+'.github/workflows/test.yml')
    snippet='''private decimal CalculateTotalPrice(
    List<BookingRoom> bookingRooms,
    DateOnly checkInDate, DateOnly checkOutDate)
{
    var numberOfNights = checkOutDate.DayNumber
        - checkInDate.DayNumber;

    return bookingRooms.Sum(br =>
        br.FinalPrice * numberOfNights);
}'''
    code=f'''<p>The booking price is calculated from each room’s final nightly price and the length of the stay.</p><div class="case-code"><span class="label">BookingService.cs · source excerpt, reformatted</span>{codeblock(snippet)}</div>{ext(H+'HotelBookingPlatform.Application/Services/BookingService.cs','Read the booking service','source-link')}'''
    reflection='''<p>This project made the relationship between validation, persistence, and testable business behavior concrete. The invoice tests are particularly useful because they describe expected outcomes.</p><p>For a next iteration, I would decouple email delivery from the booking transaction and introduce retriable background processing, while preserving clear booking ownership checks.</p>'''
    sources='<p>The repository, public API documentation, tests, and CI configuration provide different views of the implementation.</p><div class="source-grid">'+''.join(ext(u,t) for u,t in [(GITHUB+'/HotelBookingPlatform','Project repository'),('https://documenter.getpostman.com/view/27912762/2sAYXEDctG','Postman API documentation'),(H+'HotelBookingBlatform.Tests/BookingServiceTests/BookingInvoiceCalculationsTests.cs','Invoice calculation tests'),(H+'.github/workflows/test.yml','GitHub Actions build &amp; test')])+'</div>'
    return case_page('hotel-booking','Hotel Booking API','03 / Internship final project · Backend application','From finding a room to receiving the invoice.','A .NET 8 booking backend with hotel and room management, guest reservations, discounts, reviews, email notifications, and PDF invoices.','Backend Developer · Internship project','Dec 2024 — Jan 2025','Foothill Technology Solutions training',['.NET 8','EF Core','SQL Server','JWT','xUnit','FluentValidation','AutoMapper','GitHub Actions','Azure App Service'],f'<div class="case-cover illustration hotel">{HOTEL_ART}</div>','Booking-to-invoice illustration based on the API code; this is not a frontend screenshot.',[('overview','The project',overview),('contribution','What I implemented',contribution),('decisions','Engineering decisions',decisions),('code','A closer look at the code',code),('reflection','What I took forward',reflection),('sources','Explore the work',sources)],'collabrium','Collabrium')

